//! Temporary measurement of the frozen hover actor away from its training goal.
#![cfg(feature = "robots")]
#[path = "../examples/robots/learning/encoding.rs"]
mod encoding;
#[path = "../examples/robots/learning/model.rs"]
mod model;
use bevy::math::Vec3;
use bevy_gym::{Env, robots::DroneHover};

#[test]
fn measure_waypoints() {
    let policy = model::load_policy(include_bytes!("../assets/robots/recovery.mpk").to_vec()).unwrap();
    let mut rows = Vec::new();
    for seed in [0, 1, 2, 42, u64::MAX] {
        for radius in [0.0, 0.5, 1.0, 2.0, 4.0, 6.0, 8.0] {
            for direction in [Vec3::X, Vec3::NEG_X, Vec3::Z, Vec3::NEG_Z] {
                let target = Vec3::new(0.0, 2.0, 0.0) + direction * radius;
                let mut env = DroneHover::disturbed();
                let mut obs = env.reset(Some(seed)).observation;
                let mut memory = policy.initial_memory();
                let mut steps = 0;
                let mut ended = false;
                let mut min_distance = f32::MAX;
                let mut settled = 0;
                let mut peak_tilt = 0.0_f32;
                for _ in 0..1000 {
                    let mut features = encoding::encode(obs);
                    features[..3].copy_from_slice(&(obs.orientation().inverse() * (target - obs.position()) / 2.0).to_array());
                    let prediction = policy.mean_action(&features, &memory).unwrap();
                    memory = prediction.next_memory;
                    let step = env.step(encoding::decode_action(&prediction.action).unwrap());
                    obs = step.observation;
                    steps += 1;
                    let distance = obs.position().distance(target);
                    min_distance = min_distance.min(distance);
                    if distance <= 0.5 && obs.linear_velocity().length() <= 0.5 { settled += 1; } else { settled = 0; }
                    peak_tilt = peak_tilt.max((obs.orientation() * Vec3::Y).y.clamp(-1.0,1.0).acos());
                    if step.is_done() { ended = true; break; }
                }
                rows.push(serde_json::json!({"seed":seed,"target":target.to_array(),"steps":steps,"ended":ended,"final_distance":obs.position().distance(target),"minimum_distance":min_distance,"settled_actions":settled,"peak_tilt_rad":peak_tilt}));
            }
        }
    }
    std::fs::write("runs/quality-research/waypoint-probe.json", serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}

