    let policy = model::load_policy(include_bytes!("../assets/robots/recovery.mpk").to_vec()).unwrap();
    let mut rows = Vec::new();
    for seed in [0, 1, 2, 42, u64::MAX] {
        for radius in [0.0, 2.0, 4.0, 6.0, 8.0] {
            for direction in [Vec3::X, Vec3::NEG_X, Vec3::Z, Vec3::NEG_Z] {
