                    let mut motors = prediction.action;
                    for (motor, sign) in motors.iter_mut().zip([1.0, -1.0, 1.0, -1.0]) { *motor = (*motor + trim * sign).clamp(0.0, 1.0); }
                    let step = env.step(encoding::decode_action(&motors).unwrap());
                    obs = step.observation;
                    steps += 1;
                    let distance = obs.position().distance(target);
                    min_distance = min_distance.min(distance);
                    if distance <= 0.5 && obs.linear_velocity().length() <= 0.5 { settled += 1; } else { settled = 0; }
                    peak_tilt = peak_tilt.max((obs.orientation() * Vec3::Y).y.clamp(-1.0,1.0).acos());
                    if step.is_done() { ended = true; break; }
                }
                rows.push(serde_json::json!({"seed":seed,"target":target.to_array(),"steps":steps,"ended":ended,"final_distance":obs.position().distance(target),"minimum_distance":min_distance,"settled_actions":settled,"peak_tilt_rad":peak_tilt,"heading_cosine":(obs.orientation()*Vec3::NEG_Z).dot(direction)}));
            }
        }
    }
    std::fs::write("runs/quality-research/waypoint-probe-bounded-yaw.json", serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}

