//! Measure whether actor transfer can learn a heading without losing flight.
#![cfg(feature = "robots")]
#[path = "../examples/robots/learning/mod.rs"]
mod learning;
use bevy::math::Vec3;
use bevy_gym::{Env, Reset, Step, robots::{DroneHover, DroneObservation, DroneAction}, training::{RecurrentPpoAgent, RecurrentPpoPolicy, SeedConfig}};
use std::num::NonZeroU16;

struct Heading { drone: DroneHover }
impl Heading { fn new() -> Self { Self { drone: DroneHover::disturbed() } } }
impl Env for Heading {
 type Observation = DroneObservation;
 type Action = DroneAction;
 type Info = ();
 fn reset(&mut self, seed: Option<u64>) -> Reset<DroneObservation> { self.drone.reset(seed) }
 fn step(&mut self, action: DroneAction) -> Step<DroneObservation> {
  let mut result = self.drone.step(action);
  let forward = result.observation.orientation() * Vec3::NEG_Z;
  result.reward *= f64::from(0.25 + 0.75 * (-forward.z + 1.0) / 2.0);
  result
 }
}
fn features(obs: DroneObservation) -> [f32; 13] {
 let mut input = [0.0; 13];
 input[..12].copy_from_slice(&learning::encode(obs));
 let forward = obs.orientation() * Vec3::NEG_Z;
 input[12] = forward.cross(Vec3::NEG_Z).y.atan2(forward.dot(Vec3::NEG_Z)) / std::f32::consts::PI;
 input
}
fn evaluate(policy: &RecurrentPpoPolicy) -> serde_json::Value {
 let rows: Vec<_> = [0,1,2,42,u64::MAX].into_iter().map(|seed| {
  let mut env = Heading::new();
  let mut obs = env.reset(Some(seed)).observation;
  let mut memory = policy.initial_memory();
  let mut steps = 0;
  let mut reward = 0.0;
  let mut settled = 0;
  for _ in 0..500 {
   let prediction = policy.mean_action(&features(obs), &memory).unwrap();
   memory = prediction.next_memory;
   let result = env.step(learning::decode_action(&prediction.action).unwrap());
   obs = result.observation;
   reward += result.reward;
   steps += 1;
   if features(obs)[12].abs() < 0.083333336 && obs.position().distance(Vec3::new(0.0,2.0,0.0)) < 0.5 {settled+=1;}else{settled=0;}
   if result.is_done() { break; }
  }
  serde_json::json!({"seed":seed,"steps":steps,"reward":reward,"settled":settled,"distance":obs.position().distance(Vec3::new(0.0,2.0,0.0)),"yaw_error":features(obs)[12]})
 }).collect();
 serde_json::json!(rows)
}
#[test]
#[ignore]
fn train_heading() {
 let mut config = learning::learning_config();
 config.actor_learning_rate = 0.0001;
 let mut agent = RecurrentPpoAgent::load_actor_with_inserted_input_feature_and_fresh_critic("assets/robots/recovery.mpk",12,12,13,1,&[0.0;4],&[1.0;4],config,SeedConfig::from_root(7)).unwrap();
 let policy=agent.policy();
 let old = learning::load_policy(include_bytes!("../assets/robots/recovery.mpk").to_vec()).unwrap();
 let obs=DroneHover::disturbed().reset(Some(42)).observation;
 let before=old.mean_action(&learning::encode(obs),&old.initial_memory()).unwrap();
 let after=policy.mean_action(&features(obs),&policy.initial_memory()).unwrap();
 assert_eq!(before,after);
 let mut batch=learning::RecoveryBatch::with_task(7,&policy,Heading::new,features,NonZeroU16::new(500).unwrap());
 std::fs::create_dir_all("runs/quality-research/heading-probe").unwrap();
 println!("initial {}",evaluate(&policy));
 for update in 1..=600 {
  let sequences=batch.collect(&agent.policy()).unwrap();
  agent.update(&sequences).unwrap();
  if update % 20 == 0 || update == 1 {
   let policy=agent.policy();
   let evaluation=evaluate(&policy);
   println!("{update}: {evaluation}");
   std::fs::write(format!("runs/quality-research/heading-probe/{update}.json"),evaluation.to_string()).unwrap();
   std::fs::write(format!("runs/quality-research/heading-probe/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();
  }
 }
}

